<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>City Skyline Day‑Night Cycle</title>
<style>
  body,html{margin:0;padding:0;height:100%;overflow:hidden;background:#000;}
  canvas{display:block;width:100%;height:100%;}
</style>
</head>
<body>
<canvas id="sky"></canvas>
<script>
(() => {
  const canvas = document.getElementById('sky');
  const ctx = canvas.getContext('2d');

  const resize = () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  };
  window.addEventListener('resize', resize);
  resize();

  const BUILDING_COUNT = 12;
  const buildings = [];

  // create buildings
  const createBuildings = () => {
    const width = canvas.width;
    const height = canvas.height;
    const baseY = height * 0.6;
    const minW = width / (BUILDING_COUNT * 2);
    const maxW = width / BUILDING_COUNT * 1.2;
    for (let i = 0; i < BUILDING_COUNT; i++) {
      const w = minW + Math.random() * (maxW - minW);
      const h = baseY * (0.4 + Math.random() * 0.6);
      const x = i * (width / BUILDING_COUNT) + Math.random() * (width / BUILDING_COUNT - w);
      buildings.push({x, y: baseY - h, w, h, windows: []});
      // generate windows grid
      const cols = Math.floor(w / 15);
      const rows = Math.floor(h / 20);
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const wx = x + 5 + c * (w - 10) / cols;
          const wy = (baseY - h) + 5 + r * (h - 10) / rows;
          buildings[i].windows.push({x: wx, y: wy, w: (w - 10) / cols - 2, h: (h - 10) / rows - 2});
        }
      }
    }
  };
  createBuildings();

  // stars
  const stars = [];
  for (let i = 0; i < 150; i++) {
    stars.push({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height * 0.5,
      r: Math.random() * 1.5 + 0.5,
    });
  }

  const lerp = (a,b,t)=>a+(b-a)*t;
  const clamp = (v,min,max)=>Math.max(min,Math.min(max,v));

  const draw = (time) => {
    const t = (time % 10000) / 10000; // 0‑1 over 10 seconds

    // SKY -------------------------------------------------
    // t 0 = sunrise, 0.25 = day, 0.5 = sunset, 0.75 = night, 1 = sunrise again
    const skyColor = (() => {
      // use cosine to smooth transitions
      const dayFactor = 0.5 - 0.5 * Math.cos(2*Math.PI*t); // 0 at night, 1 at noon
      const r = lerp(20,135,dayFactor);
      const g = lerp(30,206,dayFactor);
      const b = lerp(70,235,dayFactor);
      return `rgb(${r|0},${g|0},${b|0})`;
    })();
    ctx.fillStyle = skyColor;
    ctx.fillRect(0,0,canvas.width,canvas.height);

    // STARS ------------------------------------------------
    const nightFactor = Math.max(0, Math.cos(2*Math.PI*t)); // 1 at midnight, 0 at noon
    ctx.fillStyle = `rgba(255,255,255,${nightFactor*0.8})`;
    stars.forEach(s=>{
      ctx.beginPath();
      ctx.arc(s.x,s.y,s.r,0,2*Math.PI);
      ctx.fill();
    });

    // SUN & MOON -------------------------------------------
    const sunMoonY = canvas.height * 0.5 * Math.sin(2*Math.PI*t - Math.PI/2) + canvas.height*0.5;
    const sunX = canvas.width * t;
    const moonX = (sunX + canvas.width/2) % canvas.width;

    // Sun (visible when above horizon)
    if (sunMoonY < canvas.height*0.6) {
      const sunRadius = 40;
      const grad = ctx.createRadialGradient(sunX, sunMoonY, 0, sunX, sunMoonY, sunRadius);
      grad.addColorStop(0,'rgba(255,255,200,0.9)');
      grad.addColorStop(1,'rgba(255,200,0,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(sunX, sunMoonY, sunRadius, 0, 2*Math.PI);
      ctx.fill();
    }

    // Moon (visible when opposite side)
    if (sunMoonY > canvas.height*0.6) {
      const moonRadius = 30;
      ctx.fillStyle = `rgba(230,230,250,${nightFactor})`;
      ctx.beginPath();
      ctx.arc(moonX, sunMoonY, moonRadius, 0, 2*Math.PI);
      ctx.fill();
    }

    // BUILDINGS --------------------------------------------
    buildings.forEach(b=>{
      // building body
      ctx.fillStyle = '#222';
      ctx.fillRect(b.x,b.y,b.w,b.h);
      // windows
      const lightProb = nightFactor * 0.7 + 0.1; // more lights at night
      b.windows.forEach(w=>{
        const lit = Math.random() < lightProb;
        ctx.fillStyle = lit ? `rgba(255,230,150,${0.6+0.4*nightFactor})` : 'rgba(20,20,30,0.2)';
        ctx.fillRect(w.x,w.y,w.w,w.h);
      });
    });

    requestAnimationFrame(draw);
  };
  requestAnimationFrame(draw);
})();
</script>
</body>
</html>
